#elif !defined PROGRAM_GBUFFERS_TERRAIN_SOLID
    if (base_color.a < 0.1) {
        discard;
        return;
    }
#endif

#if (defined PROGRAM_GBUFFERS_BLOCK || defined PROGRAM_GBUFFERS_ENTITIES || \
     defined PROGRAM_GBUFFERS_HAND) && \
    !(defined USE_SEPARATE_ENTITY_DRAWS && defined IS_IRIS)
