        mat3 new_tbn = get_tbn_matrix(normal);

        fragment_color.rgb += get_specular_reflections(
            material,
            new_tbn,
            position_screen,
            position_view,
            world_pos,
            normal,
            tbn[2],
            direction_world,
            direction_world * new_tbn,
            light_levels.y,
            is_water
