#ifdef LOD_MOD_ACTIVE
            mat3 tbn_fixed = tbn;
            if (normal.y > 0.99) {
                // Top surface: Use hardcoded TBN matrix pointing upwards that
                // is the same for LoD water and regular water
                tbn_fixed = mat3(
                    vec3(1.0, 0.0, 0.0),
                    vec3(0.0, 0.0, 1.0),
                    vec3(0.0, 1.0, 0.0)
                );
            }
#else
#define tbn_fixed tbn
#endif

            vec3 world_pos = position_scene + cameraPosition;

            vec2 coord = -(world_pos * tbn_fixed).xy;

            bool vertical_side = abs(flat_normal.y) < eps;
            bool flowing_water = abs(flat_normal.y) < 0.99 || vertical_side;

            vec2 flow_dir = vec2(0.0);
            if (vertical_side) {
                // Calculate downward direction in tangent space.
                flow_dir = (vec3(0.0, 1.0, 0.0) * tbn_fixed).xy;
            } else {
                flow_dir = flowing_water ? normalize(flat_normal.xz) : vec2(0.0);
            }

#ifdef WATER_PARALLAX
            vec3 direction_tangent = direction_world * tbn_fixed;
#ifdef SHADERLOD_PROCEDURAL_FOOTPRINT
#if defined PROGRAM_GBUFFERS_WATER && defined WATER_WAVES
            if (shaderlod_procedural_active && shaderlod_footprint_valid) {
                coord = shaderlod_displaced_coord;
            } else {
            coord = get_water_parallax_coord_lod(
                world_pos,
                direction_tangent,
                coord,
                flow_dir,
                flowing_water
            );
            }
#else // SHADERLOD_PROCEDURAL_STAGE
            coord = get_water_parallax_coord_lod(
                world_pos,
                direction_tangent,
                coord,
                flow_dir,
                flowing_water
            );
#endif // SHADERLOD_PROCEDURAL_STAGE
#else // SHADERLOD_PROCEDURAL_FOOTPRINT
            coord = get_water_parallax_coord_lod(
                world_pos,
                direction_tangent,
                coord,
                flow_dir,
                flowing_water
            );
#endif // SHADERLOD_PROCEDURAL_FOOTPRINT
#endif

#ifdef SHADERLOD_PROCEDURAL_FOOTPRINT
#if defined PROGRAM_GBUFFERS_WATER && defined WATER_WAVES
            normal_tangent = shaderlod_procedural_normal(
                world_pos, flat_normal, coord, flow_dir, light_levels.y,
                flowing_water, shaderlod_coord_dx, shaderlod_coord_dy,
                shaderlod_footprint_valid, shaderlod_footprint_confidence
            );
#else // SHADERLOD_PROCEDURAL_STAGE
            normal_tangent = get_water_normal(
                world_pos,
                flat_normal,
                coord,
                flow_dir,
                light_levels.y,
                flowing_water
            );
#endif // SHADERLOD_PROCEDURAL_STAGE
#else // SHADERLOD_PROCEDURAL_FOOTPRINT
            normal_tangent = get_water_normal(
                world_pos,
                flat_normal,
                coord,
                flow_dir,
                light_levels.y,
                flowing_water
            );
#endif // SHADERLOD_PROCEDURAL_FOOTPRINT
            normal = tbn_fixed * normal_tangent;
        }
#endif
#endif
        //------------------------------------------------------------------------//
    } else {
        // Sample textures

        fragment_color = texture(gtexture, uv, lod_bias) * tint;
#ifdef NORMAL_MAPPING
        vec3 normal_map = texture(normals, uv, lod_bias).xyz;
#endif
#ifdef SPECULAR_MAPPING
        vec4 specular_map = texture(specular, uv, lod_bias);
#endif

#ifdef FANCY_NETHER_PORTAL
        if (is_nether_portal) {
            fragment_color = draw_nether_portal(direction_world, layer_dist);
        }
#endif

#if defined PROGRAM_GBUFFERS_ENTITIES_TRANSLUCENT
        // Lightning (old versions)
        if (material_mask == MATERIAL_LIGHTNING_BOLT) {
            fragment_color = vec4(1.0);
        }

        // Hit mob tint
        fragment_color.rgb =
            mix(fragment_color.rgb, entityColor.rgb, entityColor.a);
#endif

        if (fragment_color.a < 0.1) {
            discard;
            return;
        }

        material = material_from(
            fragment_color.rgb,
            material_mask,
            world_pos,
            tbn[2],
            adjusted_light_levels
        );

#if defined PROGRAM_GBUFFERS_LIGHTNING
        if (material_mask == MATERIAL_DRAGON_BEAM) {
            material.albedo *= tint.a;
        } else {
            material.albedo = vec3(1.0);
            material.emission = vec3(1.0);
        }
#endif

        //--//

#if defined NORMAL_MAPPING && !defined NO_NORMAL
        float material_ao;
        decode_normal_map(normal_map, normal_tangent, material_ao);

        normal = tbn * normal_tangent;

        adjusted_light_levels *= mix(0.7, 1.0, material_ao);

#ifdef DIRECTIONAL_LIGHTMAPS
        adjusted_light_levels *=
            get_directional_lightmaps(position_scene, normal);
#endif
#endif

#ifdef SPECULAR_MAPPING
        decode_specular_map(specular_map, material);
#endif
    }

    // Shadows

#ifndef NO_NORMAL
    float NoL = dot(normal, light_dir);
#else
    float NoL = 1.0;
#endif
    float NoV = clamp01(dot(normal, -direction_world));
    float LoV = dot(light_dir, -direction_world);
    float halfway_norm = inversesqrt(2.0 * LoV + 2.0);
    float NoH = (NoL + NoV) * halfway_norm;
    float LoH = LoV * halfway_norm + halfway_norm;

#if defined WORLD_OVERWORLD && defined CLOUD_SHADOWS
    float cloud_shadows = get_cloud_shadows(colortex8, position_scene);
#else
#define cloud_shadows 1.0
#endif

#if defined SHADOW && (defined WORLD_OVERWORLD || defined WORLD_END)
    float sss_depth = 0.0;
    float shadow_distance_fade = 0.0;
#ifdef SHADERLOD_WATER_SHADOW_ZERO
#if defined PROGRAM_GBUFFERS_WATER && defined WORLD_OVERWORLD && defined SHADOW && !defined SHADOW_VPS
    vec3 shadows = vec3(1.0);
    if (!shaderlod_water_shadow_zero(is_water, material.albedo, NoL)) {
        shadows = get_filtered_shadows(
            position_scene,
            tbn[2],
            adjusted_light_levels.y,
            cloud_shadows,
            material.sss_amount,
            shadow_distance_fade,
            sss_depth
        );
    }
#else // SHADERLOD_WATER_SHADOW_STAGE
    vec3 shadows = get_filtered_shadows(
        position_scene,
        tbn[2],
        adjusted_light_levels.y,
        cloud_shadows,
        material.sss_amount,
        shadow_distance_fade,
        sss_depth
    );
#endif // SHADERLOD_WATER_SHADOW_STAGE
#else // SHADERLOD_WATER_SHADOW_ZERO
    vec3 shadows = get_filtered_shadows(
        position_scene,
        tbn[2],
        adjusted_light_levels.y,
        cloud_shadows,
        material.sss_amount,
        shadow_distance_fade,
        sss_depth
    );
#endif // SHADERLOD_WATER_SHADOW_ZERO
#else
#define sss_depth 0.0
#define shadow_distance_fade 0.0
    vec3 shadows = vec3(pow8(adjusted_light_levels.y));
#endif

    // Diffuse lighting

    fragment_color.rgb =
        get_diffuse_lighting(
            material,
            position_scene,
            normal,
            tbn[2],
            tbn[2],
            shadows,
            adjusted_light_levels,
            1.0,
            0.0,
            sss_depth,
#ifdef CLOUD_SHADOWS
            cloud_shadows,
#endif
            shadow_distance_fade,
            NoL,
            NoV,
            NoH,
            LoV
        ) *
        fragment_color.a;

    // Specular highlight

#if (defined WORLD_OVERWORLD || defined WORLD_END) && !defined NO_NORMAL
    fragment_color.rgb +=
        get_specular_highlight(material, NoL, NoV, NoH, LoV, LoH) *
        light_color * shadows * cloud_shadows;
#endif

    // Specular reflections

#if defined ENVIRONMENT_REFLECTIONS || defined SKY_REFLECTIONS
    if (material.ssr_multiplier > eps) {
        vec3 position_screen = vec3(
            gl_FragCoord.xy * rcp(taau_render_scale) * view_pixel_size,
            gl_FragCoord.z
        );

        mat3 new_tbn = get_tbn_matrix(normal);

        fragment_color.rgb += get_specular_reflections(
            material,
            new_tbn,
            position_screen,
            position_view,
            world_pos,
            normal,
            tbn[2],
            direction_world,
            direction_world * new_tbn,
            light_levels.y,
            is_water
        );
    }
#endif

    // Blending

#if defined PROGRAM_GBUFFERS_WATER
    if (is_water) {
        fragment_color = water_absorption_approx(
            fragment_color,
            sss_depth,
            layer_dist,
            LoV,
            dot(tbn[2], direction_world),
            cloud_shadows
        );

#ifdef SNELLS_WINDOW
        if (isEyeInWater == 1) {
            fragment_color.a =
                mix(fragment_color.a,
                    1.0,
                    fresnel_dielectric_n(NoV, air_n / water_n).x);
        }
#endif
    }
#endif

    // Fog

    vec4 fog = common_fog(length(position_scene), false);
    fragment_color.rgb = fragment_color.rgb * fog.a + fog.rgb;

    // Purkinje shift

    fragment_color.rgb =
        purkinje_shift(fragment_color.rgb, adjusted_light_levels);

    // Refraction data

#if defined PROGRAM_GBUFFERS_WATER
    refraction_data.xy = split_2x8(normal_tangent.x * 0.5 + 0.5);
    refraction_data.zw = split_2x8(normal_tangent.y * 0.5 + 0.5);
#endif
}

