                        }
                    } else { // 6-8
                        if (material_mask == 6u) { // 6
                        } else { // 7
// Sand
#ifdef HARDCODED_SPECULAR
                            float smoothness =
                                0.8 * linear_step(0.81, 0.96, hsl.z);
                            material.roughness = sqr(1.0 - smoothness);
                            material.f0 = vec3(0.02);
#endif
