                }
            } else { // 8-16
                if (material_mask < 12u) { // 8-12
                    if (material_mask < 10u) { // 8-10
                        if (material_mask == 8u) { // 8
// Ice
#ifdef HARDCODED_SPECULAR
                            float smoothness =
