mat2x3 get_lpv_fog_coefficients(vec3 position_world) {
    if (isEyeInWater == 1) {
        // Underwater

        const float density_mul = 8.0;
        const vec3 absorption_coeff = density_mul *
            vec3(WATER_ABSORPTION_R_UNDERWATER,
                 WATER_ABSORPTION_G_UNDERWATER,
