        if (shaderlod_optimization_enabled(shaderlodOptCloudSecondaryExtentCache))
            step_length *= cached_extent_scale;
        else
            step_length *= (exp2(float(step_count) + 1.0) - 2.0) /
                (exp2(float(selected_step_count) + 1.0) - 2.0);
