float shaderlod_altocumulus_extent_scale(uint original_count) {
    if (!shaderlod_optimization_enabled(shaderlodOptCloudSecondaryExtentCache)) return 1.0;
    uint selected_count = original_count;
    if (shaderlod_optimization_enabled(shaderlodOptCloudSecondaryBudget) &&
        CLOUDS_SCALE * (eyeAltitude - SEA_LEVEL) + planet_radius < clouds_altocumulus_radius - 1.0)
        selected_count = uint(shaderlod_uniform_sample_budget(shaderlodBridgeVersion,
            shaderlodEnabled, shaderlodPreset, int(original_count), 1));
