            continue;
        }
#endif
        if (clamp01(ray_pos) != ray_pos) {
            return false;
        }

        float depth = texelFetch(
                          SSRT_DEPTH_SAMPLER,
                          ivec2(ray_pos.xy * view_res * taau_render_scale),
                          0
        )
                          .x;

        if (depth < ray_pos.z &&
            abs(depth_tolerance - (ray_pos.z - depth)) < depth_tolerance) {
            hit = true;
            break;
        }
    }

    if (!hit) {
        return false;
    }

    // Refinement loop

    float final_depth;

    for (int i = 0; i < refinement_step_count; ++i) {
        ray_step *= 0.5;

        float depth = texelFetch(
                          SSRT_DEPTH_SAMPLER,
                          ivec2(ray_pos.xy * view_res * taau_render_scale),
                          0
        )
                          .x;

