void main() {
#if defined SHADERLOD_SHARED_SPATIAL && !defined GALAXY && !defined BORDER_FOG && !defined SKY_REFLECTIONS && !defined NORMAL_MAPPING && !defined SPECULAR_MAPPING && !defined SHADOW_COLOR && !defined SHADOW_VPS && !defined COLORED_LIGHTS && !defined CLOUD_SHADOWS && !defined SH_SKYLIGHT && !defined DISTANT_HORIZONS && !defined VOXY && !defined TAAU && !defined BLOCKY_CLOUDS && !defined ENVIRONMENT_REFLECTIONS && defined WORLD_OVERWORLD && defined PROGRAM_DEFERRED4
    shaderlodLightingPixel = gl_FragCoord.xy;
#endif // SHADERLOD_SHARED_SPATIAL_SCOPE

#if !defined USE_SEPARATE_ENTITY_DRAWS
    colortex3_clear = vec4(0.0);
#endif

    ivec2 texel = ivec2(gl_FragCoord.xy);

    // Sample textures

    float depth = texelFetch(combined_depth_tex, texel, 0).x;
    vec4 gbuffer_data_0 = texelFetch(colortex1, texel, 0);
#if defined NORMAL_MAPPING || defined SPECULAR_MAPPING
    vec4 gbuffer_data_1 = texelFetch(colortex2, texel, 0);
#endif
#if !defined USE_SEPARATE_ENTITY_DRAWS
    vec4 overlays = texelFetch(colortex3, texel, 0);
#endif

    // Check for LoD terrain

#ifdef LOD_MOD_ACTIVE
    float depth_mc = texelFetch(depthtex1, texel, 0).x;
    float depth_lod = texelFetch(lod_depth_tex, texel, 0).x;
    bool is_lod = is_lod_terrain(depth_mc, depth_lod);
#else
    const bool is_lod = false;
#define depth_mc depth
#endif

    // Space conversions

    bool is_hand;
    fix_hand_depth(depth_mc, is_hand);

    vec3 position_view = screen_to_view_space(
        combined_projection_matrix_inverse,
        vec3(uv, depth),
        true
    );
    vec3 position_scene = view_to_scene_space(position_view);
    vec3 position_world = position_scene + cameraPosition;
    vec3 direction_world =
        normalize(position_scene - gbufferModelViewInverse[3].xyz);
#if defined SHADERLOD_SHADOW_BUDGET && defined WORLD_OVERWORLD && defined PROGRAM_DEFERRED4 && !defined NORMAL_MAPPING && !defined SPECULAR_MAPPING && !defined SHADOW_COLOR && !defined SHADOW_VPS && !defined PIXELATED_SHADOWS && !defined DISTANT_HORIZONS && !defined VOXY
    // Draw-uniform activation; all derivatives precede sky/material/receiver branches.
    if (shaderlod_optimization_enabled(shaderlodOptShadowReceiverFootprint) && shaderlodPhotonReceiverQualified == 1) {
    vec3 receiver_normal=decode_unit_vector(unpack_unorm_2x8(gbuffer_data_0.z));
    vec2 receiver_light=unpack_unorm_2x8(gbuffer_data_0.w);
    vec3 receiver_fraction=fract(position_world+receiver_normal*0.01);
    vec3 receiver_edge=0.1-0.2*receiver_fraction;
    receiver_edge-=receiver_edge*receiver_light.y;
    vec3 receiver_bias=get_shadow_bias(position_scene,receiver_normal,dot(receiver_normal,light_dir),receiver_light.y);
    vec3 receiver_view=transform(shadowModelView,position_scene+receiver_bias+receiver_edge);
    vec3 receiver_clip=project_ortho(shadowProjection,receiver_view);
    vec2 receiver_uv=distort_shadow_space(receiver_clip).xy*0.5+0.5;
    shaderlod_receiver_dx=dFdx(receiver_uv);shaderlod_receiver_dy=dFdy(receiver_uv);
    shaderlod_receiver_clip=vec3(receiver_clip.xy,distort_shadow_space(receiver_clip).z*0.5+0.5);
    bool same_plane=all(equal(dFdx(receiver_normal),vec3(0.0))) && all(equal(dFdy(receiver_normal),vec3(0.0)));
    bool no_wrap=all(lessThanEqual(abs(dFdx(receiver_fraction)-dFdx(position_world)),vec3(1e-5))) &&
        all(lessThanEqual(abs(dFdy(receiver_fraction)-dFdy(position_world)),vec3(1e-5)));
    shaderlod_receiver_eligible=depth<1.0 && !is_hand && same_plane && no_wrap &&
        shaderlodNear>0.0 && shaderlodFar>shaderlodNear && shaderlodFar<=4096.0 &&
        shaderlodTransition>=0.0 && shaderlodTransition<=shaderlodFar-shaderlodNear &&
        shaderlodTransition*0.5<=shaderlodNear &&
        length(position_scene)>=shaderlodNear+0.5*shaderlodTransition &&
        uint(255.0*unpack_unorm_2x8(gbuffer_data_0.y).y)==0u && shadowMapResolution==2048 && MC_SHADOW_QUALITY==1.0;
    }
#endif


#if defined WORLD_OVERWORLD
    // Atmosphere

    vec3 atmosphere;
#if !defined BORDER_FOG && !defined BLOCKY_CLOUDS && defined ATMOSPHERE_SCATTERING_LUT
    if (shaderlod_optimization_enabled(shaderlodOptSkyAtmosphereOwnership)) {
        atmosphere = vec3(0.0);
        if (depth == 1.0) {
            atmosphere = shaderlod_sky_owned_atmosphere(
        direction_world,
        sun_color,
        sun_dir,
        moon_color,
        moon_dir,
        /* use_klein_nishina_phase */ depth == 1.0
    );        }
    } else {
            atmosphere = atmosphere_scattering(
        direction_world,
        sun_color,
        sun_dir,
        moon_color,
        moon_dir,
        /* use_klein_nishina_phase */ depth == 1.0
    );    }
#else
    atmosphere = atmosphere_scattering(
        direction_world,
        sun_color,
        sun_dir,
        moon_color,
        moon_dir,
        /* use_klein_nishina_phase */ depth == 1.0
    );
#endif


    // Read clouds/aurora/crepuscular rays

    float clouds_apparent_distance;
    vec4 clouds_and_aurora =
        read_clouds_and_aurora(uv, clouds_apparent_distance);

    // Blocky clouds

#ifdef BLOCKY_CLOUDS
    vec3 world_start_pos = gbufferModelViewInverse[3].xyz + cameraPosition;
    vec3 world_end_pos = position_world;

    float dither = texelFetch(noisetex, texel & 511, 0).b;
    dither = r1(frameCounter, dither);

    vec4 blocky_clouds = raymarch_blocky_clouds(
        world_start_pos,
        world_end_pos,
        depth == 1.0,
        blocky_clouds_altitude_l0,
        dither
    );

#ifdef BLOCKY_CLOUDS_LAYER_2
    float visibility = pow4(blocky_clouds.a);
    vec4 blocky_clouds_l2 = raymarch_blocky_clouds(
        world_start_pos,
        world_end_pos,
        depth == 1.0,
        blocky_clouds_altitude_l1,
        dither
    );
    blocky_clouds.rgb += blocky_clouds_l2.xyz * visibility;
    blocky_clouds.a *= mix(1.0, blocky_clouds_l2.a, visibility);
#endif

    float new_alpha = sqr(sqr(blocky_clouds.a));
    blocky_clouds.rgb +=
        atmosphere * (1.0 - new_alpha) * (blocky_clouds.a - new_alpha);
    blocky_clouds.a = new_alpha;
#endif
#endif

    if (depth == 1.0) { // Sky
#if defined SHADERLOD_SHARED_SPATIAL && !defined GALAXY && !defined BORDER_FOG && !defined SKY_REFLECTIONS && !defined NORMAL_MAPPING && !defined SPECULAR_MAPPING && !defined SHADOW_COLOR && !defined SHADOW_VPS && !defined COLORED_LIGHTS && !defined CLOUD_SHADOWS && !defined SH_SKYLIGHT && !defined DISTANT_HORIZONS && !defined VOXY && !defined TAAU && !defined BLOCKY_CLOUDS && !defined ENVIRONMENT_REFLECTIONS && defined WORLD_OVERWORLD && defined PROGRAM_DEFERRED4
        fragment_color = shaderlodPhotonSpatialResources == 1 ? texelFetch(colortex0, texel, 0).rgb :
            shaderlod_photon_original_sky(direction_world, atmosphere, clouds_and_aurora, clouds_apparent_distance);
#else // SHADERLOD_SHARED_SPATIAL_SCOPE
#if defined WORLD_OVERWORLD
        fragment_color = draw_sky(
            direction_world,
            atmosphere,
            clouds_and_aurora,
            clouds_apparent_distance
        );
#else
        fragment_color = draw_sky(direction_world);
#endif

        // Apply blocky clouds
#if defined WORLD_OVERWORLD && defined BLOCKY_CLOUDS
        fragment_color = fragment_color * blocky_clouds.w + blocky_clouds.xyz;
#endif

        // Apply common fog
        vec4 fog = common_fog(far, true);
        fragment_color = mix(fog.rgb, fragment_color.rgb, fog.a);

        // Apply purkinje shift
        fragment_color = purkinje_shift(fragment_color, vec2(0.0, 1.0));
#endif // SHADERLOD_SHARED_SPATIAL_SCOPE
    } else { // Terrain
#if defined SHADERLOD_SHARED_SPATIAL && !defined GALAXY && !defined BORDER_FOG && !defined SKY_REFLECTIONS && !defined NORMAL_MAPPING && !defined SPECULAR_MAPPING && !defined SHADOW_COLOR && !defined SHADOW_VPS && !defined COLORED_LIGHTS && !defined CLOUD_SHADOWS && !defined SH_SKYLIGHT && !defined DISTANT_HORIZONS && !defined VOXY && !defined TAAU && !defined BLOCKY_CLOUDS && !defined ENVIRONMENT_REFLECTIONS && defined WORLD_OVERWORLD && defined PROGRAM_DEFERRED4

#else // SHADERLOD_SHARED_SPATIAL_SCOPE
        // Sample ambient occlusion a while before using it (latency hiding)

        vec2 half_res_pos = gl_FragCoord.xy * (0.5 / taau_render_scale) - 0.5;

        ivec2 i = ivec2(half_res_pos);
        vec2 f = fract(half_res_pos);

        ivec2 p10 = i + ivec2(1, 0);
        ivec2 p01 = i + ivec2(0, 1);
        ivec2 p11 = i + ivec2(1, 1);

        vec4 ambient_00 = texelFetch(colortex6, i, 0);
        vec4 ambient_10 = texelFetch(colortex6, p10, 0);
        vec4 ambient_01 = texelFetch(colortex6, p01, 0);
        vec4 ambient_11 = texelFetch(colortex6, p11, 0);
        float ambient_depth_00 = texelFetch(colortex14, i, 0).x;
        float ambient_depth_10 = texelFetch(colortex14, p10, 0).x;
        float ambient_depth_01 = texelFetch(colortex14, p01, 0).x;
        float ambient_depth_11 = texelFetch(colortex14, p11, 0).x;


#endif // SHADERLOD_SHARED_SPATIAL_SCOPE
        // Unpack gbuffer data

        mat4x2 data = mat4x2(
            unpack_unorm_2x8(gbuffer_data_0.x),
            unpack_unorm_2x8(gbuffer_data_0.y),
            unpack_unorm_2x8(gbuffer_data_0.z),
            unpack_unorm_2x8(gbuffer_data_0.w)
        );

        vec3 albedo = vec3(data[0], data[1].x);
        uint material_mask = uint(255.0 * data[1].y);
        vec3 flat_normal = decode_unit_vector(data[2]);
        vec2 light_levels = data[3];

#if !defined USE_SEPARATE_ENTITY_DRAWS
        uint overlay_id = uint(255.0 * overlays.a);
        albedo = overlay_id == 0u ? albedo + overlays.rgb
                                  : albedo; // enchantment glint
        albedo = overlay_id == 1u && !is_hand
            ? 2.0 * albedo * overlays.rgb
            : albedo; // damage overlay
#endif

        // Get material and normal

        Material material = material_from(
            albedo,
            material_mask,
            position_world,
            flat_normal,
            light_levels
        );

        vec3 normal = flat_normal;
        bool parallax_shadow = false;

#ifdef LOD_MOD_ACTIVE
        if (!is_lod) {
#endif

#ifdef NORMAL_MAPPING
            normal = decode_unit_vector(gbuffer_data_1.xy);
#endif

#ifdef SPECULAR_MAPPING
            vec4 specular_map = vec4(
                unpack_unorm_2x8(gbuffer_data_1.z),
                unpack_unorm_2x8(gbuffer_data_1.w)
            );
            decode_specular_map(specular_map, material, parallax_shadow);
#elif defined NORMAL_MAPPING
        parallax_shadow = gbuffer_data_1.z >= 0.5;
#endif

#ifdef LOD_MOD_ACTIVE
        }
#endif

        // Rain puddles

#if defined WORLD_OVERWORLD && defined RAIN_PUDDLES
        if (wetness > eps && biome_may_rain > eps) {
            bool puddle = get_rain_puddles(
                position_world,
                flat_normal,
                light_levels,
                material.porosity,
                material_mask,
                normal,
                material.albedo,
                material.f0,
                material.roughness,
                material.ssr_multiplier
            );
        }
#endif

#if defined SHADERLOD_SHARED_SPATIAL && !defined GALAXY && !defined BORDER_FOG && !defined SKY_REFLECTIONS && !defined NORMAL_MAPPING && !defined SPECULAR_MAPPING && !defined SHADOW_COLOR && !defined SHADOW_VPS && !defined COLORED_LIGHTS && !defined CLOUD_SHADOWS && !defined SH_SKYLIGHT && !defined DISTANT_HORIZONS && !defined VOXY && !defined TAAU && !defined BLOCKY_CLOUDS && !defined ENVIRONMENT_REFLECTIONS && defined WORLD_OVERWORLD && defined PROGRAM_DEFERRED4
        ShaderlodSpatialResult shaderlodSpatialResult = shaderlod_spatial_full();
        ShaderlodSpatialPlan shaderlodInitialPlan = shaderlod_spatial_adapter_plan(length(position_view));
        if (!is_hand && shaderlod_photon_environment() && shaderlod_photon_material(material_mask, material)) {
#if !defined USE_SEPARATE_ENTITY_DRAWS
            if (overlays == vec4(0.0))
#endif
            shaderlodSpatialResult = shaderlod_spatial_resolve(shaderlod_photon_cache_contract(), texel,
                ivec2(view_res), shaderlodInitialPlan, shaderlod_photon_near_guard(),
                shaderlod_region_default_limits(), SHADERLOD_PHOTON_QUANTITY, frameCounter);
        }
        float ao = 1.0; float ambient_sss = 0.0; vec3 bent_normal = normal;
        if (shaderlodSpatialResult.full_resolution_required) {
        // Sample ambient occlusion a while before using it (latency hiding)

        vec2 half_res_pos = gl_FragCoord.xy * (0.5 / taau_render_scale) - 0.5;

        ivec2 i = ivec2(half_res_pos);
        vec2 f = fract(half_res_pos);

        ivec2 p10 = i + ivec2(1, 0);
        ivec2 p01 = i + ivec2(0, 1);
        ivec2 p11 = i + ivec2(1, 1);

        vec4 ambient_00 = texelFetch(colortex6, i, 0);
        vec4 ambient_10 = texelFetch(colortex6, p10, 0);
        vec4 ambient_01 = texelFetch(colortex6, p01, 0);
        vec4 ambient_11 = texelFetch(colortex6, p11, 0);
        float ambient_depth_00 = texelFetch(colortex14, i, 0).x;
        float ambient_depth_10 = texelFetch(colortex14, p10, 0).x;
        float ambient_depth_01 = texelFetch(colortex14, p01, 0).x;
        float ambient_depth_11 = texelFetch(colortex14, p11, 0).x;

        // Upscale ambient occlusion

        float lin_z = screen_to_view_space_depth(
            combined_projection_matrix_inverse,
            depth
        );

#define depth_weight(reversed_depth) \
    exp2( \
        -10.0 * \
        abs(screen_to_view_space_depth( \
                combined_projection_matrix_inverse, \
                1.0 - reversed_depth \
            ) - \
            lin_z) \
    )
        float w00 = depth_weight(ambient_depth_00) * (1.0 - f.x) * (1.0 - f.y);
        float w10 = depth_weight(ambient_depth_10) * (f.x - f.x * f.y);
        float w01 = depth_weight(ambient_depth_01) * (f.y - f.x * f.y);
        float w11 = depth_weight(ambient_depth_11) * (f.x * f.y);
#undef depth_weight

        vec4 ambient_upscaled;
        float weight_sum = w00 + w10 + w01 + w11;

        if (abs(weight_sum) > eps) {
            ambient_upscaled = ambient_00 * w00 + ambient_10 * w10 +
                ambient_01 * w01 + ambient_11 * w11;

            ambient_upscaled *= rcp(weight_sum);
        } else {
            ambient_upscaled = ambient_00;
        }

        ao = ambient_upscaled.x;
        ambient_sss = ambient_upscaled.y;

        bent_normal.xy = ambient_upscaled.zw * 2.0 - 1.0;
        bent_normal.z =
            sqrt(clamp01(1.0 - dot(bent_normal.xy, bent_normal.xy)));
        bent_normal = mat3(gbufferModelViewInverse) * bent_normal;

        // Sense check bent normal
        if (dot(bent_normal, normal) < eps) {
            bent_normal = normal;
        }

        // No AO/bent normal on hand
        if (is_hand) {
            ao = 1.0;
            bent_normal = normal;
        }

        }
#else // SHADERLOD_SHARED_SPATIAL_SCOPE
        // Upscale ambient occlusion

        float lin_z = screen_to_view_space_depth(
            combined_projection_matrix_inverse,
            depth
        );

#define depth_weight(reversed_depth) \
    exp2( \
        -10.0 * \
        abs(screen_to_view_space_depth( \
                combined_projection_matrix_inverse, \
                1.0 - reversed_depth \
            ) - \
            lin_z) \
    )
        float w00 = depth_weight(ambient_depth_00) * (1.0 - f.x) * (1.0 - f.y);
        float w10 = depth_weight(ambient_depth_10) * (f.x - f.x * f.y);
        float w01 = depth_weight(ambient_depth_01) * (f.y - f.x * f.y);
        float w11 = depth_weight(ambient_depth_11) * (f.x * f.y);
#undef depth_weight

        vec4 ambient_upscaled;
        float weight_sum = w00 + w10 + w01 + w11;

        if (abs(weight_sum) > eps) {
            ambient_upscaled = ambient_00 * w00 + ambient_10 * w10 +
                ambient_01 * w01 + ambient_11 * w11;

            ambient_upscaled *= rcp(weight_sum);
        } else {
            ambient_upscaled = ambient_00;
        }

        float ao = ambient_upscaled.x;
        float ambient_sss = ambient_upscaled.y;

        vec3 bent_normal;
        bent_normal.xy = ambient_upscaled.zw * 2.0 - 1.0;
        bent_normal.z =
            sqrt(clamp01(1.0 - dot(bent_normal.xy, bent_normal.xy)));
        bent_normal = mat3(gbufferModelViewInverse) * bent_normal;

        // Sense check bent normal
        if (dot(bent_normal, normal) < eps) {
            bent_normal = normal;
        }

        // No AO/bent normal on hand
        if (is_hand) {
            ao = 1.0;
            bent_normal = normal;
        }


#endif // SHADERLOD_SHARED_SPATIAL_SCOPE
        // Calculate lighting dot products

        float NoL = dot(normal, light_dir);
        float NoV = clamp01(dot(normal, -direction_world));
        float LoV = dot(light_dir, -direction_world);
        float halfway_norm = inversesqrt(2.0 * LoV + 2.0);
        float NoH = (NoL + NoV) * halfway_norm;
        float LoH = LoV * halfway_norm + halfway_norm;

        // Cloud shadows

